+void FCityPopulationSimulation::RetryPurchaseReservations(const FCityPlacementModel& City,
+    const UCityBuildingCatalog* Catalog, const FCityRoadNetworkSnapshot& Network, const int64 Step,
+    const FCityEconomyTuning& Tuning)
+{
+    if (!Snapshot.bUsesPurchaseReservations) return;
+    PrunePurchaseReservations(City);
+    ReservePurchases(Tuning, &City, Catalog, &Network, Step);
+}
+
+void FCityPopulationSimulation::ReservePurchases(const FCityEconomyTuning& Tuning,
+    const FCityPlacementModel* City, const UCityBuildingCatalog* Catalog,
+    const FCityRoadNetworkSnapshot* Network, const int64 Step)
+{
+    TMap<uint64, int64> Available;
+    TMap<uint64, TArray<const FCityCitizenRecord*>> Members;
+    TMap<uint64, int32> HeldStock, HeldHousehold;
+    TMap<uint64, FCityHouseholdRecord*> Households;
+    for (const auto& Citizen : Snapshot.Citizens)
+    {
+        Available.Add(Citizen.Id, FMath::Max<int64>(0, Citizen.AvailableMoney));
+        Members.FindOrAdd(Citizen.HouseholdId).Add(&Citizen);
+    }
+    for (auto& H : Snapshot.Households)
+    {
+        H.ConsumptionOrders = 0;
+        if (const auto* Group = Members.Find(H.Id))
+            for (const auto* C : *Group) H.ConsumptionOrders += C->ConsumptionNeed;
+        Households.Add(H.Id, &H);
+    }
+    // A household can shrink or change need while orders are outstanding. Keep
+    // stable older holds within the remaining daily quota; cancellation moves
+    // neither money nor stock, including an excess order already travelling.
+    TMap<uint64, int32> KeptOrders;
+    Snapshot.PurchaseReservations.RemoveAll([&](const auto& Order) {
+        const auto* H = Households.FindRef(Order.HouseholdId);
+        if (H && H->PurchasesThisMonth + KeptOrders.FindRef(H->Id) < H->ConsumptionOrders)
+        {
+            ++KeptOrders.FindOrAdd(H->Id);
+            return false;
+        }
+        if (auto* C = Snapshot.Citizens.FindByPredicate([&](const auto& Person) { return Person.Id == Order.BuyerId; }))
+            C->PendingShopEntityId = 0;
+        return true;
+    });
+    for (const auto& Order : Snapshot.PurchaseReservations)
+    {
+        ++HeldStock.FindOrAdd(Order.ShopId);
+        ++HeldHousehold.FindOrAdd(Order.HouseholdId);
+        for (const auto& C : Order.Contributions) Available.FindOrAdd(C.CitizenId) -= C.Amount;
+    }
+    // Real allocation rotates a bounded citizen slice; all citizens are revisited
+    // deterministically, including after reload. Forecast/legacy daily fixtures
+    // retain the full aggregate pass without inventing a physical route.
+    constexpr int32 RetryBudget = 32;
+    const int32 Count = Network ? FMath::Min(RetryBudget, Snapshot.Citizens.Num()) : Snapshot.Citizens.Num();
+    const int32 Start = Network && !Snapshot.Citizens.IsEmpty() ? (Step % Snapshot.Citizens.Num()) * RetryBudget % Snapshot.Citizens.Num() : 0;
+    TMap<FCityCellCoord, TMap<FCityCellCoord, int32>> DistancesByOrigin;
+    TMap<uint64, FCityCellCoord> ShopPortals;
+    if (Network)
+        for (const auto& B : Snapshot.Businesses)
+            if (!B.bIndustrial)
+            {
+                FCityCellCoord Portal;
+                if (FCityTrafficSimulation::FindPortal(*City, Catalog, B.EntityId, Portal)) ShopPortals.Add(B.EntityId, Portal);
+            }
+    const int64 Price = FMath::Max<int64>(0, Tuning.HouseholdIncomePerGoodsPurchase);
+    const int32 StepsPerDay = FMath::Max(1, Tuning.FixedStepsPerMonth);
+    for (int32 Offset = 0; Offset < Count; ++Offset)
+    {
+        auto& Buyer = Snapshot.Citizens[(Start + Offset) % Snapshot.Citizens.Num()];
+        auto* H = Households.FindRef(Buyer.HouseholdId);
+        if (!H || Buyer.bOnMedicalLeave || Buyer.IsDetained() || Buyer.IsHomeless() || Buyer.ConsumptionNeed <= 0) continue;
+        const int32 Existing = Snapshot.PurchaseReservations.IndexOfByPredicate([&](const auto& O) { return O.BuyerId == Buyer.Id; });
+        if (Existing != INDEX_NONE && (!Network || Buyer.Schedule == ECityCitizenSchedule::ToShop)) continue;
+        if (Existing == INDEX_NONE && (H->PurchasesThisMonth + HeldHousehold.FindRef(H->Id) >= H->ConsumptionOrders ||
+            Buyer.Schedule == ECityCitizenSchedule::Shop)) continue;
+        int64 Funds = 0;
+        for (const auto* C : Members.FindChecked(H->Id)) Funds += Available.FindRef(C->Id);
+        if (Existing == INDEX_NONE && Funds < Price) continue;
+        const bool HomeAfterMorning = Buyer.Schedule == ECityCitizenSchedule::Home &&
+            Buyer.NextActionStep > Step && FCityCalendar::DayIndex(Buyer.NextActionStep, StepsPerDay) > FCityCalendar::DayIndex(Step, StepsPerDay) &&
+            Step % StepsPerDay >= FCityCalendar::Duration(6.0, StepsPerDay);
+        const uint64 Origin = HomeAfterMorning || Buyer.Schedule == ECityCitizenSchedule::ToHome ? Buyer.HomeEntityId :
+            (Buyer.Schedule == ECityCitizenSchedule::Home || Buyer.Schedule == ECityCitizenSchedule::ToWork) && Buyer.WorkplaceEntityId ? Buyer.WorkplaceEntityId :
+            Buyer.CurrentLocationEntityId ? Buyer.CurrentLocationEntityId : Buyer.HomeEntityId;
+        const TMap<FCityCellCoord, int32>* Distances = nullptr;
+        if (Network)
+        {
+            FCityCellCoord Portal;
+            if (FCityTrafficSimulation::FindPortal(*City, Catalog, Origin, Portal))
+            {
+                auto* Found = DistancesByOrigin.Find(Portal);
+                if (!Found)
+                {
+                    auto& Field = DistancesByOrigin.Add(Portal);
+                    Network->FindWalkingDistances(Portal, Field);
+                    Found = &Field;
+                }
+                Distances = Found;
+            }
+        }
+        const uint64 OldShop = Existing == INDEX_NONE ? 0 : Snapshot.PurchaseReservations[Existing].ShopId;
+        const FCityBusinessLedgerRecord* Shop = nullptr;
+        int32 BestDistance = MAX_int32;
+        for (const auto& B : Snapshot.Businesses)
+        {
+            const int32 Held = HeldStock.FindRef(B.EntityId) - (B.EntityId == OldShop ? 1 : 0);
+            if (!CanReserveShop(B, Held)) continue;
+            const auto* Portal = ShopPortals.Find(B.EntityId);
+            const int32* Distance = Distances && Portal ? Distances->Find(*Portal) : nullptr;
+            if (Network && !Distance) continue;
+            const int32 Cost = Distance ? *Distance : 0;
+            if (!Shop || Cost < BestDistance || (Cost == BestDistance && B.EntityId < Shop->EntityId))
+            { Shop = &B; BestDistance = Cost; }
+        }
+        if (Existing != INDEX_NONE)
+        {
+            auto& Order = Snapshot.PurchaseReservations[Existing];
+            if (!Shop)
+            {
+                --HeldStock.FindChecked(OldShop); --HeldHousehold.FindChecked(H->Id);
+                for (const auto& C : Order.Contributions) Available.FindChecked(C.CitizenId) += C.Amount;
+                Buyer.PendingShopEntityId = 0;
+                Snapshot.PurchaseReservations.RemoveAt(Existing);
+                continue;
+            }
+            if (OldShop != Shop->EntityId)
+            {
+                --HeldStock.FindChecked(OldShop); ++HeldStock.FindOrAdd(Shop->EntityId);
+                Order.ShopId = Buyer.PendingShopEntityId = Shop->EntityId;
+            }
+        }
+        else
+        {
+            if (!Shop) continue;
+            FCityPurchaseReservation Order;
+            Order.BuyerId = Buyer.Id; Order.HouseholdId = H->Id; Order.ShopId = Shop->EntityId; Order.Price = Price;
+            int64 Remaining = Price;
+            for (const auto* C : Members.FindChecked(H->Id))
+            {
+                const int64 Amount = FMath::Min(Remaining, Available.FindRef(C->Id));
+                if (Amount > 0) { Order.Contributions.Add({C->Id, Amount}); Available.FindChecked(C->Id) -= Amount; Remaining -= Amount; }
+                if (!Remaining) break;
+            }
+            ++HeldStock.FindOrAdd(Shop->EntityId); ++HeldHousehold.FindOrAdd(H->Id);
+            Buyer.PendingShopEntityId = Shop->EntityId;
+            Snapshot.PurchaseReservations.Add(MoveTemp(Order));
+        }
+        // A newly available order can wake a home shopper after morning instead
+        // of forcing another commute or waiting until the following day.
+        if (Network && HomeAfterMorning)
+        {
+            Buyer.TripPurpose = ECityTripPurpose::Purchase;
+            Buyer.TripDestinationEntityId = Buyer.PendingShopEntityId;
+            Buyer.TripVehicleType = ECityTripVehicleType::Walk;
+            Buyer.Schedule = ECityCitizenSchedule::ToShop;
+            Buyer.CurrentLocationEntityId = Buyer.HomeEntityId;
+            Buyer.NextActionStep = Step;
+        }
+    }
 }

